import {Store} from './store.js';
import {money,day,addDays,time,fromTime,minuteNow,serviceTotal,duration,slots,turns,nextTech,quote,stats,hours,TZ} from './domain.js';

const store=new Store();
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2m-8 3h2',queue:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',pos:'M3 7h18v13H3ZM3 11h18m-13 5h3M7 4h10',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm8 .13a4 4 0 0 1 0 7.75',team:'M8 4h8v4H8ZM4 8h16v13H4Zm5 5h6m-3-3v6',gift:'M3 8h18v4H3Zm2 4v9h14v-9M12 8v13m0-13H7.5A2.5 2.5 0 1 1 10 5.5L12 8Zm0 0h4.5A2.5 2.5 0 1 0 14 5.5L12 8Z',box:'m3 7 9-4 9 4-9 4-9-4Zm0 0v10l9 4 9-4V7m-9 4v10M7.5 5 16 9',message:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H5l-3 2V11.5a9.5 9.5 0 0 1 19 0ZM7 10h10M7 14h6',chart:'M4 3v17h17M8 16v-5m5 5V7m5 9v-8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',down:'m6 9 6 6 6-6',search:'M10.5 3a7.5 7.5 0 1 0 0 15 7.5 7.5 0 0 0 0-15ZM16 16l5 5',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0ZM12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Zm0 4v5l3 2',check:'m5 12 4 4L19 6',close:'M6 6l12 12M6 18 18 6',print:'M6 9V3h12v6M6 18H3V9h18v9h-3M6 15h12v6H6Z',scan:'M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5M7 7h3v3H7Zm7 0h3v3h-3ZM7 14h3v3H7Zm7 0h3v3h-3Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM9.5 9a2.5 2.5 0 1 1 4 2c-1 .7-1.5 1-1.5 3m0 3h.01',dollar:'M12 2v20m5-15H9a3 3 0 0 0 0 6h6a3 3 0 0 1 0 6H6',menu:'M4 6h16M4 12h16M4 18h16',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',refresh:'M20 7v5h-5M4 17v-5h5M5.1 8a7 7 0 0 1 11.5-3L20 9M4 15l3.4 4A7 7 0 0 0 19 16',mail:'M3 5h18v14H3Zm0 0 9 7 9-7',pause:'M8 5v14M16 5v14',play:'m7 4 14 8-14 8Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',edit:'m14 5 5 5M3 21l5-1L21 7l-5-5L3 15Z',drawer:'M3 5h18v14H3ZM3 12h18m-11-3h4m-4 7h4'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const btn=(label,action,options={})=>`<button type="${options.type||'button'}" class="btn ${options.cls||''}" ${action?`data-action="${action}"`:''} ${options.id?`data-id="${esc(options.id)}"`:''} ${options.extra||''}>${options.icon?icon(options.icon):''}${label}</button>`;
const initials=name=>name?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()||'?';
const avatar=(name,color='',large=false)=>`<span class="avatar ${color} ${large?'large':''}">${esc(initials(name))}</span>`;
const dateLabel=(date,full=false)=>new Intl.DateTimeFormat('vi-VN',{timeZone:'UTC',...(full?{weekday:'long',day:'numeric',month:'long',year:'numeric'}:{day:'numeric',month:'short'})}).format(new Date(date+'T12:00:00Z'));
const stamp=t=>new Intl.DateTimeFormat('vi-VN',{timeZone:TZ,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(t);
const statusMap={booked:['Đã đặt','blue'],waiting:['Đang chờ','orange'],in_service:['Đang làm',''],ready:['Chờ thanh toán','green'],completed:['Hoàn tất','green'],cancelled:['Đã hủy','gray'],no_show:['Không đến','red']};
const badge=(status)=>{const [label,color]=statusMap[status]||[status,'gray'];return `<span class="badge ${color}">${label}</span>`;};
const S=()=>store.state;
const customer=id=>S().customers.find(c=>c.id===id)||{name:'Khách',phone:''};
const staff=id=>S().staff.find(t=>t.id===id)||{name:'Bất kỳ thợ',color:'',initials:'–'};
const ap=id=>S().appointments.find(a=>a.id===id);
const escapeAmount=n=>(n/100).toFixed(2);
const dollars=v=>Math.round(Number(v||0)*100);
const route=()=>location.hash.slice(1).split('?')[0]||'home';
let selectedDate=day(),selectedStaff='',calendarMode='schedule',listFilter='all',posId='',reportDays=7,reportEnd=day(),searchQuery='',stockFilter=false,staffId=new URLSearchParams(location.search).get('tech')||'T1',rendering=false,stream=null,scanTimer=null;
const nav=[['home','Tổng quan','home'],['appointments','Lịch hẹn','calendar'],['queue','Check-in & chia turn','queue'],['pos','Thanh toán','pos'],['customers','Khách hàng','users'],['team','Đội ngũ','team'],['gifts','Gift cards','gift'],['inventory','Kho vật tư','box'],['messages','Tin nhắn & email','message'],['reports','Báo cáo','chart'],['settings','Cài đặt','settings']];
const titles=Object.fromEntries(nav.map(([id,title])=>[id,title]));
function go(page){if(route()===page)render();else location.hash=page;}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
function actor(){return route()==='staff'?`Thợ demo · ${staff(staffId).name}`:route()==='kiosk'?'Kiosk demo':route()==='book'?'Khách demo':'Quản lý demo';}
async function run(type,payload={},message='Đã lưu cập nhật.'){const r=await store.run(type,payload,actor());if(message)toast(message);render();return r;}
function empty(title,description='',action=''){return `<div class="empty">${icon('spark')}<h3>${title}</h3><p>${description}</p>${action}</div>`;}
function head(title,subtitle,actions='',eyebrow='SALON WORKSPACE'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function metric(label,value,note,ic,color=''){return `<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(ic)}</span></div><strong>${value}</strong><div class="metric-note">${note}</div></div>`;}
function cardHeader(title,sub='',action=''){return `<div class="card-header"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,options,value='',extra=''){return `<label class="field"><span>${label}</span><select name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function checkField(label,name,checked=false){return `<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}><span>${label}</span></label>`;}
function syncLabel(){return store.mode==='server'?(store.connected?'Local server · đang đồng bộ':'Máy chủ local · mất kết nối'):'Đồng bộ các tab · cùng trình duyệt';}
function shell(content){const page=route(),isStaff=page==='staff';const selectedRole=isStaff?'staff':'owner';return `<div class="layout"><aside class="sidebar" id="sidebar"><a class="brand" href="#home"><span class="brand-mark">S<span>✦</span></span><div><div class="brand-name">Silver Nails</div><div class="brand-sub">SALON WORKSPACE</div></div></a><div class="location">${icon('pin')}<div>Boardman, Ohio<small>6536 South Avenue</small></div></div><div class="nav-label">${isStaff?'KHÔNG GIAN CỦA THỢ':'ĐIỀU HÀNH TIỆM'}</div><nav class="nav-group">${isStaff?`<a class="nav-item active" href="#staff">${icon('team')}Công việc của tôi</a>`:nav.slice(0,6).map(([id,label,ic])=>navLink(id,label,ic,page)).join('')}</nav>${!isStaff?`<div class="nav-label">QUẢN LÝ</div><nav class="nav-group">${nav.slice(6).map(([id,label,ic])=>navLink(id,label,ic,page)).join('')}</nav>`:''}<div class="sidebar-bottom"><div class="demo-card"><strong>✦ Không gian trải nghiệm</strong><p>Dữ liệu mẫu, thao tác thật trong demo. Chọn vai trò để thử từng màn hình.</p><button class="text-btn mt" data-action="help">Hướng dẫn dùng thử ${icon('arrow')}</button></div><div class="profile">${avatar(isStaff?staff(staffId).name:'Silver Nails')}<div><strong>${isStaff?esc(staff(staffId).name):'Chủ tiệm'}</strong><small>${isStaff?'Màn hình thợ · demo':'Quản lý · demo'}</small></div><span class="spacer"></span>${icon('down')}</div></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-menu" data-action="mobile-menu" aria-label="Mở menu">${icon('menu')}</button><span>Workspace</span><span>/</span><strong>${isStaff?'Công việc của tôi':titles[page]||'Tổng quan'}</strong></div><div class="toolbar"><button class="search-btn" data-action="search">${icon('search')}Tìm khách, lịch hẹn…<kbd>/</kbd></button><button class="icon-btn" data-action="help" aria-label="Hướng dẫn">${icon('help')}</button><select class="role-select" id="role-select" aria-label="Chọn vai trò demo">${[['owner','Chủ tiệm'],['staff','Thợ làm nails'],['guest','Khách đặt hẹn'],['kiosk','Kiosk check-in']].map(([v,l])=>`<option value="${v}" ${v===selectedRole?'selected':''}>${l}</option>`).join('')}</select>${avatar('Silver Nails')}</div></header><div class="demo-strip"><span>DEMO · Dữ liệu giả lập · Thanh toán, SMS/email và két tiền mô phỏng</span><span class="sync"><i class="dot ${store.connected?'':'off'}"></i>${syncLabel()}</span></div><main class="main" id="main">${content}</main></div></div>`;}
function navLink(id,label,ic,page){const n=id==='queue'?S().appointments.filter(a=>a.date===day()&&a.status==='waiting').length:0;return `<a class="nav-item ${page===id?'active':''}" href="#${id}">${icon(ic)}${label}${n?`<span class="count">${n}</span>`:''}</a>`;}
function publicShell(content,mode){return `<div class="public-shell"><header class="public-top"><a href="#book" class="brand"><span class="brand-mark">S<span>✦</span></span><div><div class="brand-name">Silver Nails</div><div class="brand-sub">BOARDMAN, OHIO</div></div></a><div class="actions"><a class="btn small" href="#${mode==='book'?'kiosk':'book'}">${mode==='book'?'Check-in':'Đặt lịch'}</a><a href="#home" class="btn small">${icon('home')}Quản lý demo</a></div></header><div class="demo-strip"><span>DEMO · Không gửi lịch tới tiệm · Chỉ dùng thông tin giả</span><span class="sync"><i class="dot ${store.connected?'':'off'}"></i>${syncLabel()}</span></div><main class="public-main" id="main">${content}</main><footer class="public-footer">Silver Nails · 6536 South Ave, Boardman, OH 44512 · (330) 953-3333<br>Giá, dịch vụ, thợ và giờ hoạt động trong demo là dữ liệu mẫu.</footer></div>`;}
function render(){if(!S()||rendering)return;rendering=true;const page=route();const views={home:dashboard,appointments:appointmentsView,queue:queueView,pos:posView,customers:customersView,team:teamView,gifts:giftsView,inventory:inventoryView,messages:messagesView,reports:reportsView,settings:settingsView,staff:staffView,book:bookView,kiosk:kioskView};$('#app').innerHTML=['book','kiosk'].includes(page)?publicShell((views[page])(),page):shell((views[page]||dashboard)());rendering=false;if(page==='pos')updatePos();}
function dashboard(){const today=day(),a=S().appointments.filter(a=>a.date===today),st=stats(S()),t=turns(S()),waiting=a.filter(a=>a.status==='waiting'),doing=a.filter(a=>a.status==='in_service');const upcoming=a.filter(x=>['waiting','in_service','ready','booked'].includes(x.status)).sort((a,b)=>a.start-b.start).slice(0,5);return `${head('Một ngày thật xinh, thật suôn sẻ.',dateLabel(today,true)+' · Cùng chăm chút từng trải nghiệm của khách.',btn('Lịch hẹn mới','booking',{cls:'primary',icon:'plus'}))}<div class="metrics">${metric('Doanh thu dịch vụ',money(st.net),`${st.count} hóa đơn đã hoàn tất · chưa gồm tip`,'dollar')}${metric('Lịch hẹn hôm nay',String(a.filter(a=>!['cancelled','no_show'].includes(a.status)).length).padStart(2,'0'),`<b>${doing.length} đang làm</b> · ${a.filter(a=>a.status==='completed').length} hoàn tất`,'calendar','blue')}${metric('Khách đang chờ',String(waiting.length).padStart(2,'0'),waiting.length?'Sẵn sàng nhận lượt tiếp theo':'Mọi khách đã được chăm sóc','clock','peach')}${metric('Tiền tip hôm nay',money(st.tips),'Tổng tip của đội ngũ · dữ liệu demo','spark','mint')}</div><div class="dashboard-grid"><div class="stack"><section class="card">${cardHeader('Nhịp tiệm hôm nay','Đội ngũ và thứ tự nhận khách',`<a class="text-btn" href="#queue">Bảng chia turn ${icon('arrow')}</a>`)}<div class="card-body"><div class="floor">${t.map(x=>`<div class="tech-tile">${avatar(x.name,x.color)}<h3>${esc(x.name)}</h3><span class="badge ${x.paused?'gray':x.busy?'orange':'green'}"><i class="dot ${x.paused?'off':''}"></i>${x.paused?'Đang nghỉ':x.busy?'Đang làm':'Sẵn sàng'}</span><span class="small-text">${x.used} turn · ${money(x.revenue)}</span></div>`).join('')}</div></div></section><section class="card">${cardHeader('Lịch hẹn & khách trong tiệm',`${upcoming.length} lượt cần theo dõi hôm nay`,`<a class="text-btn" href="#appointments">Xem lịch ${icon('arrow')}</a>`)}${appointmentTable(upcoming)}<div class="table-footer"><span>Cập nhật theo thao tác trong demo</span><span>${esc(time(minuteNow()))} · ET</span></div></section><section class="card">${cardHeader('Hoạt động gần đây','Mỗi thay đổi đều được ghi lại')}<div class="card-body">${S().audit.slice(0,3).map(e=>`<div class="activity"><i class="dot"></i><div><strong>${esc(e.action)}</strong><p>${esc(e.detail)}</p></div><small>${stamp(e.at)}</small></div>`).join('')}</div></section></div><aside class="stack"><div class="card insight"><span class="sparkle">✦</span><div class="eyebrow">A LITTLE CARE, A LOT OF BEAUTY</div><h2>Beautiful nails.<br>Happy moments.</h2><p>Một không gian gọn gàng để bạn dành nhiều thời gian hơn cho khách.</p>${btn('Check-in khách mới','walkin',{icon:'plus'})}</div><section class="card">${cardHeader('Thao tác nhanh')}<div class="card-body quick-list">${[['walkin','users','Đón khách walk-in','Thêm khách vào hàng chờ'],['gift-sell','gift','Bán gift card','Một món quà thật xinh'],['open-staff','team','Mở màn hình thợ','Thử đồng bộ ở tab khác']].map(([a,ic,title,sub])=>`<button class="quick-row" data-action="${a}"><span class="quick-icon">${icon(ic)}</span><span><strong>${title}</strong><small>${sub}</small></span>${icon('chevron')}</button>`).join('')}</div></section><section class="card">${cardHeader('7 ngày gần đây','Doanh thu dịch vụ demo')}<div class="card-body">${chart7()}<div class="legend"><span>Tổng doanh thu</span><b>${money(stats(S(),addDays(today,-6),today).net)}</b></div></div></section></aside></div>`;}
function chart7(){const data=Array.from({length:7},(_,i)=>{const d=addDays(day(),i-6);return {date:d,value:stats(S(),d).net};}),max=Math.max(1,...data.map(x=>x.value));return `<div class="chart" role="img" aria-label="Doanh thu 7 ngày: ${data.map(x=>dateLabel(x.date)+' '+money(x.value)).join(', ')}">${data.map((x,i)=>`<div class="bar-col"><span class="bar-label">${money(x.value).replace('.00','')}</span><div class="bar ${i===6?'today':''}" style="height:${Math.round(x.value/max*91)}px" title="${money(x.value)}"></div><small>${x.date.slice(8)}/${x.date.slice(5,7)}</small></div>`).join('')}</div>`;}
function appointmentTable(items){return !items.length?empty('Chưa có lịch hẹn','Thêm lịch mới hoặc đón khách walk-in.'): `<div class="table-wrap"><table><thead><tr><th>Khách hàng</th><th>Dịch vụ</th><th>Thợ / giờ</th><th>Trạng thái</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><div class="person">${avatar(customer(a.customerId).name)}<div><strong>${esc(customer(a.customerId).name)}</strong><small>${esc(customer(a.customerId).phone)}</small></div></td><td>${esc(a.items[0]?.name)}${a.items.length>1?` <span class="badge gray">+${a.items.length-1}</span>`:''}<small>${a.duration} phút · ${money(serviceTotal(a.items))}</small></td><td>${esc(staff(a.techId).name)}<small>${time(a.start)}</small></td><td>${badge(a.status)}</td><td><button class="icon-btn" data-action="appointment" data-id="${esc(a.id)}" aria-label="Chi tiết ${esc(customer(a.customerId).name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function appointmentsView(){const today=day(),items=S().appointments.filter(a=>a.date===selectedDate&&(!selectedStaff||a.techId===selectedStaff)&&(listFilter==='all'||a.status===listFilter)).sort((a,b)=>a.start-b.start);const ts=S().staff.filter(t=>t.active&&(!selectedStaff||t.id===selectedStaff)),[open,close]=hours(S(),selectedDate),start=Math.min(open,...items.map(a=>a.start)),startHour=Math.floor(start/60),endHour=Math.ceil(Math.max(close,...items.map(a=>a.start+a.duration))/60),n=endHour-startHour;return `${head('Lịch hẹn','Mọi cuộc hẹn, trong một nhịp nhìn.',btn('Chặn giờ','block',{icon:'clock'})+btn('Thêm lịch hẹn','booking',{cls:'primary',icon:'plus'}))}<div class="subtoolbar"><div class="actions"><button class="icon-btn" data-action="date-prev" aria-label="Ngày trước">${icon('left')}</button><input type="date" id="calendar-date" aria-label="Ngày xem lịch" value="${selectedDate}"><button class="icon-btn" data-action="date-next" aria-label="Ngày sau">${icon('chevron')}</button>${btn('Hôm nay','date-today',{cls:'small'})}<select id="calendar-staff" aria-label="Lọc thợ"><option value="">Tất cả thợ</option>${S().staff.map(t=>`<option value="${t.id}" ${selectedStaff===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="segmented"><button data-action="calendar-schedule" class="${calendarMode==='schedule'?'active':''}">Lịch theo giờ</button><button data-action="calendar-list" class="${calendarMode==='list'?'active':''}">Danh sách</button></div></div><section class="card">${cardHeader(dateLabel(selectedDate,true),`${items.length} lượt · Giờ theo America/New_York`)}${calendarMode==='list'?appointmentTable(items):`<div class="calendar-wrap"><div class="calendar"><div class="cal-head" style="grid-template-columns:55px repeat(${ts.length},1fr)"><div>ET</div>${ts.map(t=>`<div>${avatar(t.name,t.color)}${esc(t.name)}</div>`).join('')}</div><div class="cal-body" style="grid-template-columns:55px repeat(${ts.length},1fr)"><div class="cal-times">${Array.from({length:n},(_,i)=>`<div>${time((startHour+i)*60)}</div>`).join('')}</div>${ts.map(t=>`<div class="cal-lane" style="height:${n*80}px">${items.filter(a=>a.techId===t.id).map(a=>`<button class="cal-event ${t.color} ${a.status}" style="top:${(a.start-startHour*60)*80/60}px;height:${Math.max(29,a.duration*80/60-5)}px" data-action="appointment" data-id="${esc(a.id)}"><span>${time(a.start)} – ${time(a.start+a.duration)}</span><strong>${esc(customer(a.customerId).name)}</strong>${esc(a.items.map(i=>i.name).join(' + '))}</button>`).join('')}${S().blocks.filter(b=>b.date===selectedDate&&b.techId===t.id).map(b=>`<button class="cal-event block" data-action="unblock" data-id="${esc(b.id)}" style="top:${Math.max(0,(b.start-startHour*60)*80/60)}px;height:${Math.max(30,(b.end-b.start)*80/60-5)}px">${time(b.start)}–${time(b.end)}<strong>${esc(b.reason)}</strong></button>`).join('')}</div>`).join('')}</div></div></div>`}<div class="calendar-footer">${items.filter(a=>!a.techId).length} khách chưa phân thợ · <a class="text-btn" href="#queue">Xem hàng chờ</a> · Bấm vào lịch để check-in, đổi giờ hoặc hủy.</div></section>`;}
function queueView(){const items=S().appointments.filter(a=>a.date===day());const t=turns(S()),next=t.find(t=>!t.paused&&!t.busy);return `${head('Đón khách. Chia lượt. Chăm sóc.','Theo dõi từ khi khách bước vào đến khi hoàn tất dịch vụ.',btn('Mở kiosk','open-kiosk',{icon:'external'})+btn('Khách walk-in','walkin',{cls:'primary',icon:'plus'}))}<section class="card mb">${cardHeader('Thứ tự turn',`Ưu tiên ít turn nhất → lần nhận gần nhất → thứ tự thợ. Khách yêu cầu thợ ${S().settings.countRequestedTurns?'có':'không'} tính turn.`,next?`<span class="badge green">Tiếp theo: ${esc(next.name)}</span>`:'')}<div class="card-body"><div class="floor">${t.map((x,i)=>`<div class="tech-tile">${avatar(x.name,x.color)}<h3>${i+1}. ${esc(x.name)}</h3><span class="badge ${x.paused?'gray':x.busy?'orange':'green'}">${x.paused?'Đang nghỉ':x.busy?'Đang làm':`${x.used} turn`}</span><span class="small-text">${money(x.revenue)} dịch vụ hôm nay</span></div>`).join('')}</div></div></section><div class="queue-columns">${[['waiting','Khách đang chờ'],['in_service','Đang làm dịch vụ'],['ready','Sẵn sàng thanh toán']].map(([status,title])=>{const rows=items.filter(a=>a.status===status).sort((a,b)=>(a.checkedAt||0)-(b.checkedAt||0));return `<section><h2 class="column-title">${title}<span>${rows.length}</span></h2>${rows.length?rows.map(a=>queueCard(a)).join(''):empty('Chưa có khách','Các lượt mới sẽ xuất hiện ở đây.')}</section>`;}).join('')}</div>`;}
function queueCard(a,own=false){const c=customer(a.customerId),tech=staff(a.techId);return `<article class="card queue-card"><div class="person">${avatar(c.name)}<div><h3>${esc(c.name)}</h3><small>${a.requested?'Yêu cầu thợ · '+esc(tech.name):'Khách theo turn'}</small></div></div><div class="services-text">${esc(a.items.map(i=>i.name).join(' + '))}</div><div class="queue-meta"><span>${a.duration} phút · ${time(a.start)}</span><strong class="ticket-total">${money(serviceTotal(a.items))}</strong></div>${a.status==='waiting'?`<select id="assign-${esc(a.id)}" aria-label="Chọn thợ cho ${esc(c.name)}"><option value="">Tự động theo turn</option>${S().staff.filter(t=>t.active).map(t=>`<option value="${t.id}" ${t.id===a.techId?'selected':''}>${esc(t.name)}${t.paused?' · đang nghỉ':''}</option>`).join('')}</select><div class="actions">${btn('Bắt đầu','start',{cls:'primary',id:a.id,icon:'play'})}${btn('Chi tiết','appointment',{cls:'small',id:a.id})}</div>`:a.status==='in_service'?`<div class="actions"><span class="badge">${esc(tech.name)}</span><span class="spacer"></span>${btn('Hoàn tất','finish',{cls:'mint',id:a.id,icon:'check'})}</div>`:`<div class="actions"><span class="badge green">${esc(tech.name)}</span><span class="spacer"></span>${!own?btn('Thanh toán','pos-ticket',{cls:'primary',id:a.id,icon:'pos'}):'<small>Thu ngân sẽ thanh toán</small>'}</div>`}</article>`;}
function posView(){const ready=S().appointments.filter(a=>a.status==='ready'&&a.date===day());if(!ready.some(a=>a.id===posId))posId=ready[0]?.id||'';const a=ap(posId);return `${head('Thanh toán','Khép lại một trải nghiệm đẹp.',btn('Lịch sử hóa đơn','invoices',{icon:'pos'}))}<div class="pos-layout"><aside>${ready.length?ready.map(t=>`<button class="ticket ${posId===t.id?'selected':''}" data-action="pos-ticket" data-id="${esc(t.id)}"><div class="row"><strong>${esc(customer(t.customerId).name)}</strong><span>${money(serviceTotal(t.items))}</span></div><small>${esc(t.items.map(i=>i.name).join(' + '))}</small><small>${esc(staff(t.techId).name)} · Chờ thanh toán</small></button>`).join(''):empty('Không có phiếu','Hoàn tất dịch vụ để thanh toán.')}</aside><section class="card">${a?`${cardHeader(customer(a.customerId).name,`${a.id} · Dữ liệu mẫu`)}<div class="card-body"><form id="pos-form" class="pos-form"><div><div class="receipt-lines">${a.items.map(i=>`<div class="receipt-line"><div><strong>${esc(i.name)}</strong><p>${i.duration} phút · <select name="tech-${esc(i.serviceId)}" aria-label="Thợ của ${esc(i.name)}">${S().staff.map(t=>`<option value="${t.id}" ${t.id===(i.techId||a.techId)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></p></div><strong>${money(i.price)}</strong></div>`).join('')}</div><div class="field-row mt">${field('Giảm giá ($)','discount','0','number','min="0" step="0.01"')}${field('Tiền tip ($)','tip','0','number','min="0" step="0.01"')}</div><div class="tip-options">${[0,15,18,20].map(n=>btn(n===0?'Không tip':`${n}%`,'tip',{cls:'small',extra:`data-percent="${n}"`})).join('')}</div><div class="mt">${field('Gift card · nhập mã hoặc dùng máy quét USB','giftCode','','text','placeholder="SN-DEMO-0100" autocomplete="off"')}<div class="actions mt">${btn('Quét QR camera','scan-pos',{cls:'small',icon:'scan'})}<small>Thẻ mẫu có $100.00</small></div></div><div class="note mt">Thanh toán demo không thu tiền. Không nhập số thẻ ngân hàng. Bạn có thể gán thợ cho từng dịch vụ để chia doanh thu và tip.</div></div><div class="checkout-box"><div id="pos-error" class="form-error" role="alert"></div>${selectField('Phương thức phần còn lại','method',[['cash','Tiền mặt (demo)'],['card','Thẻ ngân hàng (demo)']],'cash')}<div class="mt" id="cash-field">${field('Tiền mặt khách đưa ($)','cashReceived','','number','min="0" step="0.01" placeholder="Bằng số tiền cần thu"')}</div><div id="pos-totals" class="totals"></div><button type="submit" class="btn primary full mt" id="checkout-submit">${icon('check')}Hoàn tất thanh toán demo</button><p class="mt" style="font-size:10px;text-align:center">Có thể in hóa đơn sau khi thanh toán.</p></div></form></div>`:empty('Sẵn sàng khi khách hoàn tất','Vào bảng chia turn để hoàn tất một dịch vụ.',`<a class="btn primary" href="#queue">Đến bảng chia turn</a>`)}</section></div>`;}
function posPayload(validateCash=true){const form=$('#pos-form');if(!form)return null;const f=new FormData(form),allocations={};for(const [k,v]of f)if(k.startsWith('tech-'))allocations[k.slice(5)]=v;return {appointmentId:posId,discount:dollars(f.get('discount')),tip:dollars(f.get('tip')),giftCode:f.get('giftCode'),method:f.get('method'),cashReceived:validateCash&&f.get('cashReceived')!==''?dollars(f.get('cashReceived')):undefined,allocations};}
function updatePos(){const form=$('#pos-form');if(!form)return;try{const q=quote(S(),posPayload(false));$('#pos-error').textContent='';$('#checkout-submit').disabled=false;$('#cash-field').classList.toggle('hidden',q.method!=='cash');$('#pos-totals').innerHTML=`<div><span>Dịch vụ</span><span>${money(q.subtotal)}</span></div><div><span>Giảm giá</span><span>−${money(q.discount)}</span></div><div><span>Thuế mẫu (${S().settings.taxBasisPoints/100}%)</span><span>${money(q.tax)}</span></div><div><span>Tip</span><span>${money(q.tip)}</span></div><div class="grand-total"><span>Tổng</span><span>${money(q.total)}</span></div>${q.giftUsed?`<div><span>Gift card</span><span>−${money(q.giftUsed)}</span></div>`:''}<div><strong>Cần thu ${q.method==='cash'?'tiền mặt':'thẻ'}</strong><strong>${money(q.due)}</strong></div>${q.method==='cash'&&form.elements.cashReceived.value!==''?`<div><span>Tiền thừa</span><span>${money(Math.max(0,dollars(form.elements.cashReceived.value)-q.due))}</span></div>`:''}`;}catch(e){$('#pos-error').textContent=e.message;$('#checkout-submit').disabled=true;$('#pos-totals').innerHTML='';}}
function customersView(){const list=S().customers.filter(c=>(c.name+' '+c.phone+' '+c.email).toLowerCase().includes(searchQuery.toLowerCase()));return `${head('Nhớ từng khách, chăm chút từng lần.','Hồ sơ, sở thích và lịch sử ghé tiệm.',btn('Thêm khách','customer-new',{cls:'primary',icon:'plus'}))}<div class="subtoolbar"><input type="search" id="customer-search" placeholder="Tìm tên, điện thoại, email…" aria-label="Tìm khách hàng" value="${esc(searchQuery)}"><small>${list.length} hồ sơ demo</small></div><section class="card"><div class="table-wrap"><table><thead><tr><th>Khách hàng</th><th>Liên hệ</th><th>Lượt hoàn tất</th><th>Chi tiêu dịch vụ</th><th>Nhận tin</th><th></th></tr></thead><tbody>${list.map(c=>{const inv=S().invoices.filter(i=>i.customerId===c.id&&!i.refunded);return `<tr><td><div class="person">${avatar(c.name)}<strong>${esc(c.name)}</strong></div></td><td>${esc(c.phone)}<small>${esc(c.email||'Chưa có email')}</small></td><td>${inv.length} lượt</td><td class="amount">${money(inv.reduce((v,i)=>v+i.net,0))}</td><td><span class="badge ${c.consent?'green':'gray'}">${c.consent?'Đồng ý nhận tin':'Chưa đồng ý'}</span></td><td>${btn('Hồ sơ','customer',{cls:'small',id:c.id})}</td></tr>`;}).join('')}</tbody></table></div>${!list.length?empty('Không tìm thấy khách','Thử một tên hoặc số điện thoại khác.'):''}</section>`;}
function teamView(){const t=turns(S());return `${head('Một đội ngũ, cùng một nhịp.','Tên nhân viên và mức hoa hồng đều là mẫu.',btn('Thêm thợ','staff-add',{icon:'plus'})+btn('Mở app thợ','open-staff',{cls:'primary',icon:'external'}))}<div class="grid-3">${t.map(x=>`<article class="card staff-card"><div class="staff-top">${avatar(x.name,x.color,true)}<span class="badge ${x.paused?'gray':x.busy?'orange':'green'}">${x.paused?'Đang nghỉ':x.busy?'Đang làm':'Sẵn sàng'}</span></div><h2>${esc(x.name)}</h2><small>Thợ demo · Mức chia mẫu ${S().settings.commissionRate}%</small><div class="staff-stat"><div><strong>${x.used}</strong><small>Turn hôm nay</small></div><div><strong>${money(x.revenue)}</strong><small>Doanh thu dịch vụ</small></div></div><div class="actions">${btn(x.paused?'Vào ca':'Nghỉ giải lao','pause',{cls:'small',id:x.id,icon:x.paused?'play':'pause'})}${btn('Mở workspace','staff-open',{cls:'small primary',id:x.id})}</div></article>`).join('')}</div><section class="card section-gap">${cardHeader('Giờ nghỉ đã chặn','Các khoảng giờ này không thể đặt hẹn',btn('Thêm giờ nghỉ','block',{cls:'small',icon:'plus'}))}${S().blocks.length?`<div class="table-wrap"><table><thead><tr><th>Thợ</th><th>Ngày</th><th>Khoảng giờ</th><th>Lý do</th><th></th></tr></thead><tbody>${S().blocks.map(b=>`<tr><td>${esc(staff(b.techId).name)}</td><td>${dateLabel(b.date)}</td><td>${time(b.start)}–${time(b.end)}</td><td>${esc(b.reason)}</td><td>${btn('Bỏ chặn','unblock',{cls:'small',id:b.id})}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có giờ nghỉ cố định','Dùng “Thêm giờ nghỉ” để chặn lịch theo ngày.')}</section>`;}
function giftsView(){return `${head('Một chút xinh đẹp, gửi tặng ai đó.','Bán thẻ, quét QR, kiểm tra số dư và dùng khi thanh toán.',btn('Tra mã / quét QR','gift-lookup',{icon:'scan'})+btn('Bán gift card','gift-sell',{cls:'primary',icon:'plus'}))}<div class="metrics">${metric('Số dư đang lưu hành',money(S().giftCards.reduce((v,g)=>v+g.balance,0)),'Bao gồm thẻ bị khóa · tiền demo','gift')}${metric('Thẻ đã phát hành',S().giftCards.length,'Mỗi thẻ có mã và QR riêng','scan','blue')}${metric('Bán thẻ hôm nay',money(stats(S()).giftSales),'Tách khỏi doanh thu dịch vụ','dollar','mint')}${metric('Đã dùng hôm nay',money(stats(S()).gift),'Trừ vào hóa đơn đã thanh toán','pos','peach')}</div><div class="grid-3">${S().giftCards.map(g=>`<article class="card"><div class="gift-visual"><div class="gift-brand">Silver Nails <span style="float:right">✦</span></div><div class="gift-title">A GIFT OF BEAUTY · DEMO</div><div class="gift-amount">${money(g.balance)}</div><div class="gift-code">${esc(g.code)}</div></div><div class="gift-bottom"><div><strong>${esc(g.recipient)}</strong><small>${g.voided?'Đã khóa':g.balance?'Sẵn sàng sử dụng':'Đã dùng hết'}</small></div>${btn('QR & chi tiết','gift-detail',{cls:'small',id:g.id})}</div></article>`).join('')}</div>`;}
function inventoryView(){const list=S().inventory.filter(x=>!stockFilter||x.stock<=x.min);return `${head('Mọi thứ sẵn sàng, cho ngày mới.','Theo dõi vật tư bằng điều chỉnh nhập / sử dụng thủ công.',btn('Chỉ xem sắp hết','stock-filter',{cls:stockFilter?'primary':'',icon:'box'}))}<section class="card"><div class="table-wrap"><table><thead><tr><th>Vật tư</th><th>Tồn kho</th><th>Ngưỡng nhắc</th><th>Trạng thái</th><th>Điều chỉnh</th></tr></thead><tbody>${list.map(x=>`<tr><td><strong>${esc(x.name)}</strong><small>${esc(x.id)}</small></td><td>${x.stock} ${esc(x.unit)}</td><td>${x.min} ${esc(x.unit)}</td><td><span class="badge ${x.stock<=x.min?'orange':'green'}">${x.stock<=x.min?'Cần bổ sung':'Đủ dùng'}</span></td><td>${btn('Nhập / sử dụng','stock-adjust',{cls:'small',id:x.id})}</td></tr>`).join('')}</tbody></table></div></section><section class="card section-gap">${cardHeader('Nhật ký tồn kho')}${S().stockLog.length?`<div class="table-wrap"><table><thead><tr><th>Vật tư</th><th>Thay đổi</th><th>Lý do</th><th>Giờ</th></tr></thead><tbody>${S().stockLog.slice(0,30).map(l=>`<tr><td>${esc(S().inventory.find(x=>x.id===l.itemId)?.name)}</td><td>${l.delta>0?'+':''}${l.delta}</td><td>${esc(l.reason)}</td><td>${stamp(l.at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có điều chỉnh','Nhập hoặc trừ kho để xem lịch sử tại đây.')}</section>`;}
function messagesView(){return `${head('Giữ kết nối với từng khách.','Xem trước nội dung tự động sau đặt lịch, thanh toán và nhắc hẹn.',btn('Tạo nhắc hẹn ngày mai','reminders',{icon:'clock'})+btn('Chạy gửi mô phỏng','messages-run',{cls:'primary',icon:'play'}))}<div class="note">Đây là hộp tin demo. Không có SMS hoặc email thực nào được gửi. Tin tự động chỉ được tạo khi hồ sơ khách đã đồng ý nhận tin và quy tắc tương ứng được bật.</div><div class="grid-2"><section class="card">${cardHeader('Hộp tin tự động',`${S().messages.filter(m=>m.status==='queued').length} tin trong hàng đợi`)}${S().messages.length?S().messages.slice(0,60).map(m=>`<article class="message"><div class="message-top"><strong>${esc(m.name)} <span class="badge ${m.channel==='SMS'?'blue':''}">${esc(m.channel)}</span></strong><span class="badge ${m.status==='queued'?'orange':'green'}">${m.status==='queued'?'Chờ mô phỏng':'Đã mô phỏng'}</span></div><p>${esc(m.body)}</p><small>${esc(m.to)} · ${stamp(m.created)} · Chưa gửi ra ngoài</small></article>`).join(''):empty('Chưa có tin nhắn','Đặt lịch bằng hồ sơ đã đồng ý nhận tin để thử.')}</section><div class="stack"><section class="card">${cardHeader('Các quy tắc đang dùng')}<div class="card-body">${[['bookingMessages','Xác nhận đặt hẹn','Tạo ngay khi có lịch mới.'],['reminderMessages','Nhắc hẹn trước một ngày','Bấm tạo nhắc hẹn để chạy bộ lập lịch demo.'],['receiptMessages','Email hóa đơn','Tạo sau khi thanh toán.'],['followupMessages','Hỏi thăm sau dịch vụ','Tạo nội dung mẫu sau thanh toán.']].map(([key,title,sub])=>`<div class="quick-row"><span class="quick-icon">${icon(key==='receiptMessages'?'mail':'message')}</span><span><strong>${title}</strong><small>${sub}</small></span><span class="badge ${S().settings[key]?'green':'gray'}" style="margin-left:auto">${S().settings[key]?'Bật':'Tắt'}</span></div>`).join('')}<a class="btn full mt" href="#settings">Thay đổi quy tắc</a></div></section><div class="note">Chạy thật cần một máy chủ lập lịch cùng nhà cung cấp SMS/email. Demo đã có hàng đợi và chống tạo trùng lời nhắc cho cùng lịch, ngày và giờ.</div></div></div>`;}
function staffEarnings(id,from,to){let revenue=0,tips=0,commission=0;for(const i of S().invoices.filter(i=>i.date>=from&&i.date<=to&&!i.refunded)){const weights=i.items.map(x=>x.price);const allocate=total=>{const sum=weights.reduce((a,b)=>a+b,0);if(!sum)return weights.map((_,n)=>n===0?total:0);const vals=weights.map(w=>Math.floor(total*w/sum));let remain=total-vals.reduce((a,b)=>a+b,0);const order=weights.map((w,n)=>({n,r:(total*w)%sum})).sort((a,b)=>b.r-a.r||a.n-b.n);for(let j=0;j<remain;j++)vals[order[j].n]++;return vals;};const net=allocate(i.net),tip=allocate(i.tip),com=allocate(Math.round(i.net*(i.commissionRate??S().settings.commissionRate)/100));i.items.forEach((x,n)=>{if(x.techId===id){revenue+=net[n];tips+=tip[n];commission+=com[n];}});}return {revenue,tips,commission,total:commission+tips};}
function reportsView(){const from=addDays(reportEnd,1-reportDays),st=stats(S(),from,reportEnd);const invoices=S().invoices.filter(i=>i.date>=from&&i.date<=reportEnd);return `${head('Các con số, thật rõ ràng.',`${dateLabel(from)} – ${dateLabel(reportEnd)} · Doanh thu dịch vụ sau giảm giá, bỏ các hóa đơn đã hoàn.`,btn('Xuất CSV','export-csv',{icon:'download'})+btn('Xem hóa đơn','invoices',{cls:'primary',icon:'pos'}))}<div class="subtoolbar"><div class="segmented">${[[1,'Hôm nay'],[7,'7 ngày'],[30,'30 ngày']].map(([n,l])=>`<button data-action="report-range" data-days="${n}" class="${reportDays===n?'active':''}">${l}</button>`).join('')}</div><label class="field"><span>Đến ngày</span><input type="date" id="report-end" value="${reportEnd}"></label></div><div class="metrics">${metric('Doanh thu dịch vụ',money(st.net),`${st.count} hóa đơn hoàn tất`,'dollar')}${metric('Tiền tip',money(st.tips),'Chia theo tỷ trọng giá dịch vụ','spark','mint')}${metric('Giá trị trung bình',money(st.count?Math.round(st.net/st.count):0),'Doanh thu dịch vụ / số hóa đơn','chart','blue')}${metric('Bán gift card',money(st.giftSales),'Không cộng vào doanh thu dịch vụ','gift','peach')}</div><div class="grid-2"><section class="card">${cardHeader('Đối soát thanh toán','Các hóa đơn còn hiệu lực trong khoảng đã chọn')}<div class="card-body"><div class="totals">${[['Tiền mặt',st.cash],['Thẻ ngân hàng (mô phỏng)',st.card],['Gift card đã dùng',st.gift],['Thuế mẫu',st.tax],['Tổng thu hóa đơn',st.total]].map(([label,n])=>`<div><span>${label}</span><strong>${money(n)}</strong></div>`).join('')}</div><p class="mt" style="font-size:10px">Tổng thu = dịch vụ + thuế + tip. Báo cáo điều chỉnh theo ngày hóa đơn gốc khi hoàn tiền; chưa phải sổ kế toán dòng tiền theo ngày hoàn.</p></div></section><section class="card">${cardHeader('Doanh thu 7 ngày đến hôm nay')}<div class="card-body">${chart7()}</div></section></div><section class="card section-gap">${cardHeader('Bảng chia tiền thợ (demo)','Hoa hồng được chốt theo mức cài đặt lúc lập hóa đơn; tip chia theo tỷ trọng giá dịch vụ.')}<div class="table-wrap"><table><thead><tr><th>Thợ</th><th>Doanh thu sau giảm</th><th>Hoa hồng</th><th>Tip</th><th>Tổng nhận mẫu</th></tr></thead><tbody>${S().staff.map(t=>{const e=staffEarnings(t.id,from,reportEnd);return `<tr><td><div class="person">${avatar(t.name,t.color)}<strong>${esc(t.name)}</strong></div></td><td>${money(e.revenue)}</td><td>${money(e.commission)}</td><td>${money(e.tips)}</td><td><strong>${money(e.total)}</strong></td></tr>`;}).join('')}</tbody></table></div></section><div class="note mt">${invoices.filter(i=>i.refunded).length} hóa đơn đã hoàn trong kỳ gốc, được loại khỏi các tổng ở trên. Hoa hồng là quy tắc mẫu để thử, chưa bao gồm lương, thuế thu nhập hoặc điều chỉnh tiền công.</div>`;}
function settingsView(){const c=S().settings;return `${head('Theo cách tiệm của bạn vận hành.','Cài đặt demo, menu dịch vụ, thiết bị và dữ liệu.',btn('Hướng dẫn','help',{icon:'help'}))}<div class="grid-2"><section class="card">${cardHeader('Quy tắc vận hành')}<form id="settings-form"><div class="card-body form-grid"><div class="field-row">${field('Mở cửa (thứ 2–6)','open',time(c.open),'time','required')}${field('Đóng cửa (thứ 2–6)','close',time(c.close),'time','required')}</div><small>Thứ 7: 09:00–18:00 · Chủ nhật: 10:00–17:00 · Giờ mẫu ET</small><div class="field-row">${field('Thuế mẫu (%)','tax',c.taxBasisPoints/100,'number','min="0" max="25" step="0.01" required')}${field('Hoa hồng thợ (%)','commission',c.commissionRate,'number','min="0" max="100" step="1" required')}</div>${checkField('Tính turn cho khách yêu cầu thợ','countRequestedTurns',c.countRequestedTurns)}${checkField('Tạo SMS xác nhận hẹn (demo)','bookingMessages',c.bookingMessages)}${checkField('Tạo nhắc hẹn ngày mai (demo)','reminderMessages',c.reminderMessages)}${checkField('Tạo email hóa đơn (demo)','receiptMessages',c.receiptMessages)}${checkField('Tạo tin hỏi thăm sau dịch vụ (demo)','followupMessages',c.followupMessages)}<div class="note">Thuế mặc định 0% chỉ để mô phỏng; không phải cấu hình thuế áp dụng cho tiệm. Các vai trò chủ/thợ/khách là chế độ xem demo, chưa phải đăng nhập hay phân quyền bảo mật.</div><button class="btn primary" type="submit">${icon('check')}Lưu cài đặt</button></div></form></section><div class="stack"><section class="card">${cardHeader('Dữ liệu & đồng bộ',store.mode==='server'?'SQLite trên máy chủ local · SSE giữa thiết bị':'IndexedDB của trình duyệt · đồng bộ tab cùng origin')}<div class="card-body"><div class="actions">${btn('Tải backup JSON','backup',{icon:'download'})}${btn('Khôi phục backup','restore',{icon:'upload'})}</div><p class="mt" style="font-size:11px;line-height:1.8">Backup chứa toàn bộ dữ liệu demo. Có thể tự lưu file backup vào OneDrive. Chưa có kết nối hoặc tự động sao lưu OneDrive.</p><div class="note mt">GitHub Pages lưu riêng trên mỗi trình duyệt. Muốn nhiều máy cùng dữ liệu, chạy <strong>npm run start:lan</strong> trong thư mục mã nguồn trên máy chủ của tiệm và mở cùng địa chỉ LAN. Xem README trong repo.</div>${btn('Tạo lại dữ liệu mẫu','reset',{cls:'danger small',icon:'refresh'})}</div></section><section class="card">${cardHeader('Kết nối thiết bị','In bằng trình duyệt; két tiền và terminal là mô phỏng.')}<div class="card-body"><div class="device-grid">${[['printer','print','Máy in','In thử qua hộp thoại trình duyệt'],['drawer','drawer','Két tiền','Ghi lại lệnh mở két mô phỏng'],['scanner','scan','Máy quét QR','USB scanner nhập mã như bàn phím']].map(([kind,ic,title,sub])=>`<div class="device">${icon(ic)}<h3>${title}</h3><p>${sub}</p>${btn('Kiểm tra','device',{cls:'small',extra:`data-kind="${kind}"`})}</div>`).join('')}</div>${S().devices.slice(0,4).map(d=>`<div class="activity"><div><strong>${esc(d.detail)}</strong><p>${stamp(d.at)}</p></div><span class="badge gray">demo</span></div>`).join('')}</div></section></div></div><section class="card section-gap">${cardHeader('Menu dịch vụ','Giá và thời lượng mẫu; sửa menu không làm thay đổi phiếu đã tạo.',btn('Thêm dịch vụ','service-add',{cls:'small',icon:'plus'}))}<div class="table-wrap"><table><thead><tr><th>Dịch vụ</th><th>Nhóm</th><th>Giá</th><th>Thời lượng</th><th>Trạng thái</th><th></th></tr></thead><tbody>${S().services.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${esc(x.category)}</td><td>${money(x.price)}</td><td>${x.duration} phút</td><td><span class="badge ${x.active?'green':'gray'}">${x.active?'Đang nhận':'Tạm ẩn'}</span></td><td>${btn('Sửa','service-edit',{cls:'small',id:x.id})}</td></tr>`).join('')}</tbody></table></div></section>`;}
function staffView(){if(!S().staff.some(t=>t.id===staffId))staffId=S().staff[0].id;const t=staff(staffId),items=S().appointments.filter(a=>a.techId===staffId&&a.date===day()),e=staffEarnings(staffId,day(),day());return `${head(`Chào ${esc(t.name)}, hôm nay thế nào?`,'Công việc, lượt khách và thu nhập của riêng bạn.',`<select id="staff-picker" aria-label="Chọn thợ demo">${S().staff.map(t=>`<option value="${t.id}" ${t.id===staffId?'selected':''}>${esc(t.name)}</option>`).join('')}</select>`+btn(t.paused?'Vào ca':'Nghỉ giải lao','pause',{id:staffId,cls:'primary',icon:t.paused?'play':'pause'}),'MY WORKSPACE')}<div class="metrics">${metric('Khách hôm nay',items.filter(a=>!['cancelled','no_show'].includes(a.status)).length,'Chỉ những lượt được phân cho bạn','users')}${metric('Doanh thu dịch vụ',money(e.revenue),'Sau giảm giá · hóa đơn đã thanh toán','dollar','blue')}${metric('Tiền tip',money(e.tips),'Tip được chia theo giá dịch vụ','spark','mint')}${metric('Tổng nhận mẫu',money(e.total),'Hoa hồng đã chốt + tiền tip','chart','peach')}</div><div class="note">Mở màn hình chủ ở một tab khác rồi giao khách cho ${esc(t.name)}. Thay đổi sẽ tự xuất hiện tại đây. Màn hình thợ là chế độ xem thử; chưa có đăng nhập bảo mật.</div><div class="queue-columns">${[['waiting','Khách được giao'],['in_service','Tôi đang làm'],['ready','Chờ thu ngân']].map(([status,label])=>`<section><h2 class="column-title">${label}<span>${items.filter(a=>a.status===status).length}</span></h2>${items.filter(a=>a.status===status).map(a=>queueCard(a,true)).join('')||empty('Chưa có khách','Lượt được phân sẽ xuất hiện tại đây.')}</section>`).join('')}</div><section class="card section-gap">${cardHeader('Lịch của tôi hôm nay')}${appointmentTable(items)}</section>`;}
function bookView(){return `<div class="public-hero"><div class="eyebrow">YOUR MOMENT OF BEAUTY</div><h1>A little time for you.<br>A little beauty, too.</h1><p>Chọn dịch vụ yêu thích và một khung giờ dành riêng cho bạn. Thử trải nghiệm đặt hẹn tại Silver Nails.</p>${btn('Đặt lịch hẹn demo','booking',{cls:'primary',icon:'calendar'})}</div><div class="grid-3">${[['Hands','Đôi tay thật xinh','Từ classic manicure đến gel và nail art, chọn một phong cách của riêng bạn.','spark'],['Feet','Một chút thư giãn','Signature hoặc Deluxe Spa Pedicure, dành thời gian chăm sóc đôi chân.','gift'],['Enhancements','Dấu ấn của bạn','Full set và fill, kết hợp màu sắc và dáng móng bạn yêu thích.','team']].map(([cat,title,desc,ic])=>`<article class="card public-card">${icon(ic)}<h2>${title}</h2><p>${desc}</p>${S().services.filter(s=>s.category===cat&&s.active).map(s=>`<div class="receipt-line"><span>${esc(s.name)}</span><strong>${money(s.price)}</strong></div>`).join('')}</article>`).join('')}</div><section class="card section-gap public-card"><h2>Bạn đã có lịch hẹn?</h2><p>Tra cứu bằng số điện thoại demo để xem, đổi hoặc hủy lịch. Trong bản dùng thật, bước này sẽ cần xác minh khách.</p><form id="guest-lookup" class="kiosk-search"><input name="phone" type="tel" placeholder="Số điện thoại đặt hẹn" aria-label="Số điện thoại đặt hẹn" required><button type="submit" class="btn">${icon('search')}Tìm lịch demo</button></form></section>`;}
function kioskView(){return `<div class="public-hero"><div class="eyebrow">WELCOME TO SILVER NAILS</div><h1>Rất vui được đón bạn.</h1><p>Nhập số điện thoại để tìm lịch hôm nay, hoặc chọn walk-in để vào hàng chờ.</p></div><section class="card public-card"><form id="kiosk-lookup" class="kiosk-search"><input name="phone" type="tel" inputmode="tel" placeholder="Số điện thoại · ví dụ 3305550110" aria-label="Số điện thoại check-in" required><button type="submit" class="btn primary">${icon('search')}Tìm lịch hôm nay</button></form><div id="kiosk-results"></div></section><div class="grid-2 section-gap"><article class="card public-card">${icon('users')}<h2>Chưa có lịch hẹn?</h2><p>Chọn dịch vụ, điền thông tin mẫu và đội ngũ sẽ nhận lượt của bạn.</p>${btn('Tôi là khách walk-in','walkin',{cls:'primary',icon:'plus'})}</article><article class="card public-card">${icon('gift')}<h2>Bạn có gift card?</h2><p>Kiểm tra số dư bằng mã trên thẻ hoặc quét mã QR. Dùng gift card khi thanh toán.</p>${btn('Tra gift card demo','gift-lookup',{icon:'scan'})}</article></div>`;}

let pendingConfirm=null;
function stopScan(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}if(scanTimer){clearInterval(scanTimer);scanTimer=null;}}
function closeModal(){stopScan();$('#modal').close();}
function modal(title,body,footer=''){stopScan();const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Đóng hộp thoại">${icon('close')}</button></div><div class="modal-body"><div id="modal-error" class="form-error" role="alert"></div>${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!el.open)el.showModal();}
function confirmAction(title,body,callback,label='Xác nhận'){pendingConfirm=callback;modal(title,`<p style="font-size:13px;line-height:1.9">${body}</p>`,btn('Quay lại','close')+btn(label,'confirm',{cls:'primary'}));}
function bookingForm(walkin=false){modal(walkin?'Đón khách walk-in':'Tạo lịch hẹn mới',`<form id="booking-form" class="form-grid" data-walkin="${walkin}"><div class="note">Chỉ nhập thông tin giả để dùng thử. Dịch vụ, giá và nhân viên trong demo là mẫu.</div><div><div class="section-title">1. Chọn dịch vụ</div><div class="service-picker">${S().services.filter(s=>s.active).map(s=>`<label class="service-option"><input type="checkbox" name="services" value="${s.id}"><strong>${esc(s.name)}</strong><small>${money(s.price)} · ${s.duration} phút</small></label>`).join('')}</div><div id="booking-summary" class="booking-summary"><span>Chưa chọn dịch vụ</span><strong>$0.00</strong></div></div><div><div class="section-title">2. ${walkin?'Chọn thợ (không bắt buộc)':'Chọn ngày & thợ'}</div><div class="${walkin?'':'field-row'}">${!walkin?field('Ngày hẹn','date',addDays(day(),1),'date',`required min="${day()}" max="${addDays(day(),60)}"`):''}${selectField('Thợ yêu thích','techId',[['','Bất kỳ thợ · theo turn'],...S().staff.filter(t=>t.active).map(t=>[t.id,t.name])])}</div>${!walkin?'<div id="booking-slots" class="mt"><small>Chọn dịch vụ để xem giờ trống.</small></div>':'<p class="mt" style="font-size:11px">Khách được thêm vào hàng chờ. Quản lý sẽ phân thợ và bắt đầu dịch vụ.</p>'}</div><div><div class="section-title">3. Thông tin khách</div><div class="field-row">${field('Tên khách','name','','text','required minlength="2" maxlength="80" placeholder="Ví dụ: Demo Nguyen" autocomplete="off"')}${field('Điện thoại (10 chữ số)','phone','','tel','required placeholder="3305550123" autocomplete="off"')}</div><div class="mt">${field('Email (không bắt buộc)','email','','email','placeholder="demo@example.com" autocomplete="off"')}</div><label class="field mt"><span>Ghi chú</span><textarea name="notes" maxlength="500" placeholder="Dáng móng, màu yêu thích…"></textarea></label><div class="mt">${checkField('Tôi đồng ý nhận tin về lịch hẹn và dịch vụ. Trong demo, chỉ tạo bản xem trước, không gửi tin.','consent')}</div></div><button type="submit" class="btn primary full">${icon('check')}${walkin?'Check-in vào hàng chờ':'Xác nhận lịch demo'}</button></form>`);}
function updateBooking(){const form=$('#booking-form');if(!form)return;const ids=new FormData(form).getAll('services'),items=S().services.filter(s=>ids.includes(s.id));$('#booking-summary').innerHTML=`<span>${items.length} dịch vụ · ${duration(items)} phút</span><strong>${money(serviceTotal(items))}</strong>`;if(form.dataset.walkin==='true')return;const previous=form.elements.start?.value,values=items.length?slots(S(),form.elements.date.value,items,form.elements.techId.value):[];$('#booking-slots').innerHTML=values.length?`<label class="field"><span>Giờ trống · Eastern Time</span></label><div class="slot-grid">${values.map(m=>`<label class="slot"><input type="radio" name="start" value="${m}" ${String(m)===previous?'checked':''} required><span>${time(m)}</span></label>`).join('')}</div>`:`<div class="note">${items.length?'Không có giờ phù hợp. Đổi ngày hoặc chọn thợ khác.':'Chọn ít nhất một dịch vụ để xem giờ trống.'}</div>`;}
function bookingSuccess(a,walkin=false){modal(walkin?'Bạn đã check-in':'Lịch demo đã được tạo',`<div class="success-view"><div class="success-icon">${icon('check')}</div><h3>${walkin?'Bạn đang ở hàng chờ.':'Hẹn bạn một ngày thật xinh.'}</h3><p>${esc(customer(a.customerId).name)} · ${dateLabel(a.date)} · ${walkin?'Chờ phân lượt':time(a.start)+' ET'}<br>${esc(a.items.map(i=>i.name).join(' + '))}</p><div class="success-code">${esc(a.id)}</div><p>${walkin?'Quản lý và màn hình thợ sẽ cập nhật theo thao tác.':'Lịch chỉ thuộc demo; không gửi tới tiệm thật.'}</p></div>`,(!walkin?btn('Tải lịch .ics','calendar-download',{id:a.id,icon:'calendar'}):'')+btn('Xong','close',{cls:'primary'}));}
function appointmentDetail(id){const a=ap(id);if(!a)throw new Error('Không tìm thấy lịch.');const c=customer(a.customerId);modal('Chi tiết lịch hẹn',`<div class="person">${avatar(c.name,'',true)}<div><h2>${esc(c.name)}</h2><small>${esc(c.phone)}</small></div><span class="spacer"></span>${badge(a.status)}</div><div class="detail-list">${[['Mã hẹn',a.id],['Ngày & giờ',`${dateLabel(a.date,true)} · ${time(a.start)} ET`],['Thợ',staff(a.techId).name],['Thời lượng',`${a.duration} phút`],['Dịch vụ',a.items.map(i=>i.name).join(' + ')],['Giá dịch vụ',money(serviceTotal(a.items))],['Ghi chú',a.notes||'Không có']].map(([k,v])=>`<div><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="actions">${a.status==='booked'?`${a.date===day()?btn('Check-in','checkin',{cls:'primary',id}):''}${btn('Đổi lịch','reschedule',{id,icon:'calendar'})}${btn('Hủy lịch','cancel',{cls:'danger',id})}${btn('Không đến','noshow',{id})}`:''}${a.status==='waiting'?btn('Hủy lượt','cancel',{cls:'danger',id}):''}${a.status==='in_service'?btn('Hoàn tất dịch vụ','finish',{cls:'mint',id}):''}${a.status==='ready'?btn('Thanh toán','pos-ticket',{cls:'primary',id}):''}${a.invoiceId?btn('Xem hóa đơn','receipt',{id:a.invoiceId,icon:'pos'}):''}${btn('Tải lịch .ics','calendar-download',{id,icon:'download'})}</div>`);}
function rescheduleForm(id){const a=ap(id);modal('Đổi lịch hẹn',`<form id="reschedule-form" data-id="${esc(id)}" class="form-grid"><p>${esc(customer(a.customerId).name)} · ${a.duration} phút</p><div class="field-row">${field('Ngày mới','date',a.date,'date',`required min="${day()}" max="${addDays(day(),60)}"`)}${selectField('Thợ','techId',S().staff.filter(t=>t.active).map(t=>[t.id,t.name]),a.techId)}</div><div id="reschedule-slots"></div><button class="btn primary" type="submit">Lưu lịch mới</button></form>`);updateReschedule();}
function updateReschedule(){const f=$('#reschedule-form');if(!f)return;const a=ap(f.dataset.id),values=slots(S(),f.elements.date.value,a.items,f.elements.techId.value,a.id),previous=f.elements.start?.value||String(a.start);$('#reschedule-slots').innerHTML=values.length?`<div class="slot-grid">${values.map(m=>`<label class="slot"><input type="radio" name="start" value="${m}" ${String(m)===previous?'checked':''} required><span>${time(m)}</span></label>`).join('')}</div>`:'<div class="note">Không còn giờ trống phù hợp. Hãy đổi ngày.</div>';}
function customerForm(id=''){const c=id?customer(id):{name:'',phone:'',email:'',notes:'',consent:false};const history=S().invoices.filter(i=>i.customerId===id);modal(id?'Hồ sơ khách hàng':'Thêm khách hàng',`<form id="customer-form" data-id="${esc(id)}" class="form-grid"><div class="field-row">${field('Tên khách','name',c.name,'text','required minlength="2" maxlength="80"')}${field('Điện thoại','phone',c.phone,'tel',id?'readonly':'required')}</div>${field('Email','email',c.email,'email')}<label class="field"><span>Sở thích / ghi chú</span><textarea name="notes" maxlength="1000">${esc(c.notes)}</textarea></label>${checkField('Đồng ý nhận tin hẹn / dịch vụ (mô phỏng)','consent',c.consent)}<button class="btn primary" type="submit">Lưu hồ sơ</button></form>${history.length?`<div class="mt"><h3>Lịch sử thanh toán</h3><div class="search-results">${history.map(i=>`<button class="search-result" data-action="receipt" data-id="${esc(i.id)}"><strong>${dateLabel(i.date)} · ${money(i.total)} ${i.refunded?'· Đã hoàn':''}</strong><small>${esc(i.items.map(x=>x.name).join(' + '))}</small></button>`).join('')}</div></div>`:''}`);}
function giftSellForm(){modal('Bán gift card demo',`<form id="gift-form" class="form-grid"><div class="gift-visual"><div class="gift-brand">Silver Nails <span style="float:right">✦</span></div><div class="gift-title">A GIFT OF BEAUTY · DEMO</div><div class="gift-amount" id="gift-preview">$100.00</div></div>${field('Người nhận','recipient','','text','required minlength="2" maxlength="80" placeholder="Ví dụ: Taylor Demo"')}<div class="field-row">${field('Mệnh giá ($)','amount','100','number','min="5" max="2000" step="0.01" required')}${selectField('Thanh toán mô phỏng','method',[['cash','Tiền mặt'],['card','Thẻ ngân hàng']])}</div><div class="note">Không thu tiền thật. Gift card demo chỉ có giá trị trong dữ liệu thử này.</div><button class="btn primary" type="submit">${icon('gift')}Phát hành gift card demo</button></form>`);}
function drawQR(code,target='gift-qr'){const node=document.getElementById(target);if(!node)return;if(!window.QRCode){node.textContent='Không tải được mã QR. Dùng mã chữ bên dưới.';return;}node.innerHTML='';new window.QRCode(node,{text:code,width:174,height:174,colorDark:'#32293d',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});}
function giftDetail(id){const g=S().giftCards.find(x=>x.id===id);if(!g)throw new Error('Gift card không tồn tại.');modal('Gift card · QR & số dư',`<div id="gift-print"><div class="gift-visual"><div class="gift-brand">Silver Nails ✦</div><div class="gift-title">GIFT CARD · DEMO ONLY</div><div class="gift-amount">${money(g.balance)}</div><div class="gift-code">${esc(g.code)}</div></div><div class="qr" id="gift-qr" aria-label="QR chứa mã gift card ${esc(g.code)}"></div><p style="text-align:center;font-size:12px">${esc(g.recipient)} · ${g.voided?'Thẻ đang khóa':'Thẻ demo'}<br><strong>${esc(g.code)}</strong></p></div><div class="detail-list">${g.ledger.map(l=>`<div><span>${{sale:'Phát hành',redeem:'Sử dụng',refund:'Hoàn vào thẻ'}[l.kind]||esc(l.kind)} · ${dateLabel(l.date)}</span><strong>${money(l.amount)}</strong></div>`).join('')}</div>`,btn(g.voided?'Mở khóa':'Khóa thẻ','gift-toggle',{id:g.id})+btn('In gift card','gift-print',{cls:'primary',id:g.id,icon:'print'}));drawQR(g.code);}
function lookupGiftForm(){modal('Tra cứu gift card',`<form id="gift-lookup-form" class="form-grid">${field('Mã gift card / máy quét USB','code','','text','required placeholder="SN-DEMO-0100" autocomplete="off" autofocus')}<button class="btn primary" type="submit">${icon('search')}Kiểm tra số dư</button></form><div class="mt">${btn('Quét bằng camera','scan-gift',{icon:'scan'})}</div>`);}
async function scanQR(destination){modal('Quét mã QR',`<div class="note">Máy quét USB có thể nhập mã trực tiếp vào ô gift card. Camera cần trình duyệt hỗ trợ BarcodeDetector và HTTPS hoặc localhost.</div><video id="scan-video" class="scan-video" playsinline muted></video><p class="mt" id="scan-status">Đang kiểm tra camera…</p>`,btn('Đóng','close'));try{if(!('BarcodeDetector'in window))throw new Error('Trình duyệt này chưa hỗ trợ đọc QR bằng camera. Hãy nhập mã hoặc dùng máy quét USB.');const formats=await BarcodeDetector.getSupportedFormats();if(!formats.includes('qr_code'))throw new Error('Thiết bị chưa hỗ trợ QR. Hãy nhập mã trên thẻ.');if(!navigator.mediaDevices?.getUserMedia)throw new Error('Camera cần HTTPS hoặc localhost. Hãy nhập mã hoặc dùng máy quét USB.');const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(!$('#scan-video')||!$('#modal').open){media.getTracks().forEach(t=>t.stop());return;}stream=media;const video=$('#scan-video');video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});$('#scan-status').textContent='Đưa QR gift card vào khung hình.';let detecting=false;scanTimer=setInterval(async()=>{if(detecting)return;detecting=true;try{const codes=await detector.detect(video);if(codes[0]){const code=codes[0].rawValue.trim().toUpperCase();stopScan();if(destination==='pos'){closeModal();$('#pos-form').elements.giftCode.value=code;updatePos();}else{const g=S().giftCards.find(x=>x.code===code);if(g)giftDetail(g.id);else{$('#scan-status').textContent='Không tìm thấy mã này trong dữ liệu demo.';}}}}catch{}finally{detecting=false;}},350);}catch(e){if($('#scan-status'))$('#scan-status').textContent=e.message;stopScan();}}
function receiptHTML(i){return `<div class="receipt-preview"><h3>Silver Nails</h3><p>6536 South Ave, Boardman, OH 44512<br>(330) 953-3333</p><p class="demo-stamp">DEMO · NO REAL PAYMENT</p><div>${esc(i.id)}<br>${dateLabel(i.date)} · ${stamp(i.created)}<br>${esc(i.customerName)}${i.refunded?'<br><strong>REFUNDED / ĐÃ HOÀN</strong>':''}</div><div class="mt">${i.items.map(x=>`<div class="receipt-line"><span>${esc(x.name)}<br><small>${esc(staff(x.techId).name)}</small></span><span>${money(x.price)}</span></div>`).join('')}</div><div class="totals">${[['Dịch vụ',i.subtotal],['Giảm giá',-i.discount],['Thuế',i.tax],['Tip',i.tip]].map(([k,n])=>`<div><span>${k}</span><span>${money(n)}</span></div>`).join('')}<div class="grand-total"><span>Tổng</span><span>${money(i.total)}</span></div>${i.giftUsed?`<div><span>Gift card</span><span>${money(i.giftUsed)}</span></div>`:''}<div><span>${i.method==='cash'?'Tiền mặt':'Thẻ demo'}</span><span>${money(i.due)}</span></div>${i.method==='cash'?`<div><span>Khách đưa</span><span>${money(i.cashReceived)}</span></div><div><span>Tiền thừa</span><span>${money(i.change)}</span></div>`:''}</div><p class="mt">Beautiful Nails · Confident You<br>Thank you for visiting!<br>Hóa đơn mô phỏng, không có giá trị giao dịch.</p></div>`;}
function receiptModal(id){const i=S().invoices.find(x=>x.id===id);if(!i)throw new Error('Không tìm thấy hóa đơn.');modal('Hóa đơn demo',receiptHTML(i),(i.refunded?'':btn('Hoàn tiền demo','refund',{cls:'danger',id:i.id}))+btn('In hóa đơn','receipt-print',{cls:'primary',id:i.id,icon:'print'}));}
function printHTML(html){$('#print-area').innerHTML=html;window.print();}
function invoiceList(){modal('Lịch sử hóa đơn',`<div class="search-results">${S().invoices.slice().sort((a,b)=>b.created-a.created).map(i=>`<button class="search-result" data-action="receipt" data-id="${esc(i.id)}"><strong>${esc(i.customerName)} · ${money(i.total)} ${i.refunded?'· Đã hoàn':''}</strong><small>${dateLabel(i.date)} · ${esc(i.id)} · ${i.method==='cash'?'Tiền mặt':'Thẻ demo'}</small></button>`).join('')||empty('Chưa có hóa đơn')}</div>`);}
function refundForm(id){const i=S().invoices.find(x=>x.id===id);modal('Hoàn toàn bộ hóa đơn demo',`<form id="refund-form" data-id="${esc(id)}" class="form-grid"><div class="note">Hoàn ${money(i.total)} cho ${esc(i.customerName)}. ${i.giftUsed?money(i.giftUsed)+' sẽ được cộng lại vào gift card gốc. ':''}Không có giao dịch tiền thật. Thao tác không tạo lại phiếu để thu lần hai.</div>${field('Lý do hoàn tiền','reason','','text','required minlength="3" maxlength="160"')}<button class="btn danger" type="submit">Xác nhận hoàn tiền demo</button></form>`);}
function blockForm(){modal('Chặn giờ của thợ',`<form id="block-form" class="form-grid"><div class="field-row">${selectField('Thợ','techId',S().staff.filter(t=>t.active).map(t=>[t.id,t.name]))}${field('Ngày','date',selectedDate,'date','required')}</div><div class="field-row">${field('Từ','start','12:00','time','required')}${field('Đến','end','13:00','time','required')}</div>${field('Lý do','reason','Nghỉ trưa','text','maxlength="160"')}<button class="btn primary" type="submit">Lưu giờ nghỉ</button></form>`);}
function serviceForm(id=''){const x=S().services.find(s=>s.id===id)||{name:'',price:2500,duration:30,category:'Hands',active:true};modal(id?'Sửa dịch vụ':'Thêm dịch vụ',`<form id="service-form" data-id="${esc(id)}" class="form-grid">${field('Tên dịch vụ','name',x.name,'text','required minlength="2" maxlength="80"')}<div class="field-row">${field('Giá ($)','price',escapeAmount(x.price),'number','required min="0" max="2000" step="0.01"')}${field('Thời lượng (phút)','duration',x.duration,'number','required min="5" max="480" step="5"')}</div>${selectField('Nhóm','category',['Hands','Feet','Enhancements','Extras'].map(s=>[s,s]),x.category)}${checkField('Đang nhận dịch vụ này','active',x.active)}<button class="btn primary" type="submit">Lưu dịch vụ</button></form>`);}
function help(){modal('Bắt đầu một vòng trải nghiệm',`<div class="help-steps"><div class="help-step"><div><strong>Đón một khách mới</strong>Bấm “Khách walk-in”, chọn dịch vụ và nhập tên / số điện thoại giả.</div></div><div class="help-step"><div><strong>Phân lượt cho thợ</strong>Trong “Check-in & chia turn”, để tự động hoặc chọn thợ rồi “Bắt đầu”.</div></div><div class="help-step"><div><strong>Mở màn hình thợ</strong>Dùng nút “Mở app thợ” ở trang Đội ngũ. Chọn đúng thợ để thấy khách vừa được giao.</div></div><div class="help-step"><div><strong>Hoàn tất và thanh toán</strong>Thợ bấm “Hoàn tất”, chủ vào “Thanh toán”. Thử tip, giảm giá, gift card SN-DEMO-0100 và in hóa đơn.</div></div><div class="help-step"><div><strong>Kiểm tra kết quả</strong>Xem doanh thu, hoa hồng, số dư thẻ, lịch sử khách và bản xem trước SMS/email.</div></div></div><div class="note mt">GitHub Pages: cùng trình duyệt, nhiều tab. Máy chủ local: nhiều thiết bị cùng Wi-Fi. Mọi vai trò là demo; không nhập thông tin khách thật.</div>`,btn('Bắt đầu thử','close',{cls:'primary'}));}
function searchModal(){modal('Tìm trong workspace',`<input type="search" id="global-search" class="full" style="width:100%" placeholder="Tên khách, điện thoại, mã hẹn…" aria-label="Tìm trong workspace" autofocus><div id="global-results" class="search-results"><p>Nhập ít nhất 2 ký tự.</p></div>`);}
function updateSearch(value){const q=value.trim().toLowerCase();$('#global-results').innerHTML=q.length<2?'<p>Nhập ít nhất 2 ký tự.</p>':S().customers.filter(c=>(c.name+' '+c.phone).toLowerCase().includes(q)).slice(0,8).map(c=>`<button class="search-result" data-action="customer" data-id="${esc(c.id)}"><strong>${esc(c.name)}</strong><small>${esc(c.phone)} · Hồ sơ khách</small></button>`).join('')+S().appointments.filter(a=>(a.id+' '+customer(a.customerId).name).toLowerCase().includes(q)).slice(0,8).map(a=>`<button class="search-result" data-action="appointment" data-id="${esc(a.id)}"><strong>${esc(customer(a.customerId).name)} · ${dateLabel(a.date)} ${time(a.start)}</strong><small>${esc(a.id)} · ${statusMap[a.status]?.[0]}</small></button>`).join('')||empty('Không tìm thấy kết quả');}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const from=addDays(reportEnd,1-reportDays);const rows=[['Invoice','Date','Customer (demo)','Service revenue USD','Discount USD','Tax USD','Tip USD','Total USD','Gift USD','Other payment USD','Method','Refunded']];S().invoices.filter(i=>i.date>=from&&i.date<=reportEnd).forEach(i=>rows.push([i.id,i.date,i.customerName,escapeAmount(i.net),escapeAmount(i.discount),escapeAmount(i.tax),escapeAmount(i.tip),escapeAmount(i.total),escapeAmount(i.giftUsed),escapeAmount(i.due),i.method,i.refunded?'Yes':'No']));const cell=v=>{let str=String(v);if(/^[=+\-@\t\r\n]/.test(str))str="'"+str;return '"'+str.replaceAll('"','""')+'"';};download(`Silver-Nails-${from}-${reportEnd}.csv`,'\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function calendarDownload(id){const a=ap(id);const escapeICS=v=>String(v).replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const value=m=>a.date.replaceAll('-','')+'T'+time(m).replace(':','')+'00';const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Silver Nails Demo//EN','CALSCALE:GREGORIAN','BEGIN:VTIMEZONE','TZID:America/New_York','BEGIN:DAYLIGHT','DTSTART:20070311T020000','RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=2SU','TZOFFSETFROM:-0500','TZOFFSETTO:-0400','TZNAME:EDT','END:DAYLIGHT','BEGIN:STANDARD','DTSTART:20071104T020000','RRULE:FREQ=YEARLY;BYMONTH=11;BYDAY=1SU','TZOFFSETFROM:-0400','TZOFFSETTO:-0500','TZNAME:EST','END:STANDARD','END:VTIMEZONE','BEGIN:VEVENT',`UID:${a.id}@silver-nails-demo`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}`,`DTSTART;TZID=America/New_York:${value(a.start)}`,`DTEND;TZID=America/New_York:${value(a.start+a.duration)}`,'SUMMARY:Silver Nails - DEMO appointment',`DESCRIPTION:${escapeICS(a.items.map(i=>i.name).join(' + ')+' · DEMO ONLY; no appointment sent to salon.')}`,'LOCATION:6536 South Ave\, Boardman\, OH 44512','END:VEVENT','END:VCALENDAR'].join('\r\n');download(`Silver-Nails-${a.id}.ics`,content,'text/calendar;charset=utf-8');}
function openTab(hash,tech=''){const url=new URL(location.href);url.search=tech?'?tech='+encodeURIComponent(tech):'';url.hash=hash;window.open(url.href,'_blank','noopener');}
async function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>5_000_000)throw new Error('File vượt quá 5 MB.');const data=JSON.parse(await file.text());const {validateBackup}=await import('./domain.js');validateBackup(data);confirmAction('Khôi phục dữ liệu?',`File <strong>${esc(file.name)}</strong> chứa ${data.appointments.length} lịch, ${data.invoices.length} hóa đơn. Dữ liệu demo hiện tại sẽ được thay thế.`,async()=>{await store.replace(data);closeModal();render();toast('Đã khôi phục dữ liệu.');},'Khôi phục');}catch(e){toast(e.message,true);}};input.click();}

document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
  try {
    switch(action){
      case 'close':closeModal();break;
      case 'confirm':{const fn=pendingConfirm;pendingConfirm=null;el.disabled=true;if(fn)await fn();break;}
      case 'help':help();break;
      case 'mobile-menu':$('#sidebar').classList.toggle('open');break;
      case 'search':searchModal();break;
      case 'booking':bookingForm();break;
      case 'walkin':bookingForm(true);break;
      case 'appointment':appointmentDetail(id);break;
      case 'date-prev':selectedDate=addDays(selectedDate,-1);render();break;
      case 'date-next':selectedDate=addDays(selectedDate,1);render();break;
      case 'date-today':selectedDate=day();render();break;
      case 'calendar-list':calendarMode='list';render();break;
      case 'calendar-schedule':calendarMode='schedule';render();break;
      case 'checkin':{await run('checkin',{id},'Khách đã vào hàng chờ.');if(route()==='kiosk'||route()==='book')bookingSuccess(ap(id),true);else appointmentDetail(id);break;}
      case 'start':{el.disabled=true;const techId=$(`[id="assign-${id}"]`)?.value;await run('start',{id,techId},'Đã giao khách và bắt đầu dịch vụ.');break;}
      case 'finish':{el.disabled=true;await run('finish',{id},'Đã hoàn tất dịch vụ, chờ thu ngân.');if($('#modal').open)closeModal();break;}
      case 'cancel':case 'noshow':confirmAction(action==='cancel'?'Hủy lịch / lượt khách?':'Đánh dấu không đến?',`Lịch của <strong>${esc(customer(ap(id).customerId).name)}</strong> sẽ được cập nhật.`,async()=>{await run(action,{id});closeModal();});break;
      case 'reschedule':rescheduleForm(id);break;
      case 'calendar-download':calendarDownload(id);break;
      case 'pos-ticket':posId=id;closeModal();go('pos');break;
      case 'tip':{const subtotal=serviceTotal(ap(posId).items)-dollars($('#pos-form').elements.discount.value);$('#pos-form').elements.tip.value=escapeAmount(Math.round(subtotal*Number(el.dataset.percent)/100));updatePos();break;}
      case 'invoices':invoiceList();break;
      case 'receipt':receiptModal(id);break;
      case 'receipt-print':{const invoice=S().invoices.find(x=>x.id===id);await store.run('device',{kind:'printer',detail:`In qua trình duyệt · ${invoice.id}`},actor());printHTML(receiptHTML(invoice));break;}
      case 'refund':refundForm(id);break;
      case 'customer':customerForm(id);break;
      case 'customer-new':customerForm();break;
      case 'pause':await run('staffPause',{id});break;
      case 'staff-add':modal('Thêm thợ demo',`<form id="staff-form" class="form-grid">${field('Tên hiển thị','name','','text','required minlength="2" maxlength="50"')}<button class="btn primary" type="submit">Thêm thợ</button></form>`);break;
      case 'staff-open':staffId=id;openTab('staff',id);break;
      case 'open-staff':openTab('staff',staffId);break;
      case 'open-kiosk':openTab('kiosk');break;
      case 'block':blockForm();break;
      case 'unblock':confirmAction('Bỏ chặn giờ?',`Khoảng giờ nghỉ này sẽ được mở lại để nhận lịch hẹn.`,async()=>{await run('unblock',{id});closeModal();});break;
      case 'gift-sell':giftSellForm();break;
      case 'gift-detail':giftDetail(id);break;
      case 'gift-lookup':lookupGiftForm();break;
      case 'gift-toggle':await run('giftToggle',{id});giftDetail(id);break;
      case 'gift-print':{const g=S().giftCards.find(x=>x.id===id);const html=$('#gift-print').cloneNode(true);html.querySelector('.qr').id='print-qr';$('#print-area').innerHTML='';$('#print-area').append(html);drawQR(g.code,'print-qr');window.print();break;}
      case 'scan-pos':await scanQR('pos');break;
      case 'scan-gift':await scanQR('gift');break;
      case 'stock-filter':stockFilter=!stockFilter;render();break;
      case 'stock-adjust':{const x=S().inventory.find(x=>x.id===id);modal('Điều chỉnh tồn kho',`<form id="stock-form" data-id="${esc(id)}" class="form-grid"><p>${esc(x.name)} · Hiện có ${x.stock} ${esc(x.unit)}</p>${field('Số lượng thay đổi (âm = sử dụng)','delta','1','number','required min="-10000" max="10000" step="1"')}${field('Lý do','reason','','text','required minlength="2" maxlength="160" placeholder="Ví dụ: nhập hàng / sử dụng trong ca"')}<button class="btn primary" type="submit">Lưu điều chỉnh</button></form>`);break;}
      case 'messages-run':await run('messageSimulate',{},'Đã chạy mô phỏng. Không có tin nào gửi ra ngoài.');break;
      case 'reminders':{const r=await run('reminders',{},'');toast(`Đã tạo ${r.count} lời nhắc demo cho ngày mai.`);break;}
      case 'report-range':reportDays=Number(el.dataset.days);reportEnd=day();render();break;
      case 'export-csv':exportCSV();break;
      case 'service-add':serviceForm();break;
      case 'service-edit':serviceForm(id);break;
      case 'backup':download(`Silver-Nails-backup-${day()}.json`,JSON.stringify(S(),null,2),'application/json');toast('Đã tải bản sao dữ liệu demo.');break;
      case 'restore':await importBackup();break;
      case 'reset':confirmAction('Tạo lại toàn bộ dữ liệu mẫu?',`Tất cả thay đổi bạn đã thử trong demo này sẽ bị xóa và thay bằng dữ liệu mẫu mới. Bạn có thể tải backup trước khi làm.`,async()=>{await store.replace(null,true);closeModal();render();toast('Đã tạo lại dữ liệu mẫu.');},'Tạo lại dữ liệu');break;
      case 'device':{const kind=el.dataset.kind;if(kind==='scanner')lookupGiftForm();else{await run('device',{kind,detail:kind==='drawer'?'Lệnh mở két mô phỏng · không kết nối phần cứng':'In thử bằng trình duyệt'},kind==='drawer'?'Đã ghi lệnh mở két mô phỏng.':'Đang mở hộp thoại in.');if(kind==='printer')printHTML('<div class="receipt-preview"><h3>Silver Nails</h3><p>PRINTER TEST · DEMO</p><p>6536 South Ave, Boardman</p><hr><p>0123456789<br>In bằng trình duyệt, không phải kết nối ESC/POS trực tiếp.</p></div>');}break;}
    }
  }catch(e){if($('#modal').open&&$('#modal-error'))$('#modal-error').textContent=e.message;else toast(e.message,true);el.disabled=false;}
});
document.addEventListener('change',event=>{const el=event.target;try{
  if(el.id==='role-select'){go({owner:'home',staff:'staff',guest:'book',kiosk:'kiosk'}[el.value]);return;}
  if(el.id==='calendar-date'){selectedDate=el.value||day();render();}
  if(el.id==='calendar-staff'){selectedStaff=el.value;render();}
  if(el.id==='staff-picker'){staffId=el.value;render();}
  if(el.id==='report-end'){reportEnd=el.value||day();render();}
  if(el.closest('#booking-form')&&['services','date','techId'].includes(el.name))updateBooking();
  if(el.closest('#reschedule-form')&&['date','techId'].includes(el.name))updateReschedule();
  if(el.closest('#pos-form'))updatePos();
}catch(e){toast(e.message,true);}});
let searchTimer;
document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search')updateSearch(el.value);if(el.closest('#pos-form'))updatePos();if(el.id==='customer-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const position=el.selectionStart;searchQuery=el.value;render();const next=$('#customer-search');next?.focus();next?.setSelectionRange(position,position);},250);}if(el.closest('#gift-form')&&el.name==='amount')$('#gift-preview').textContent=money(dollars(el.value));});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const f=new FormData(form),data=Object.fromEntries(f),submit=$('[type="submit"]',form);if(submit?.disabled)return;if(submit)submit.disabled=true;if($('#modal-error'))$('#modal-error').textContent='';
  try{
    switch(form.id){
      case 'booking-form':{const walkin=form.dataset.walkin==='true';if(!walkin&&data.start===undefined)throw new Error('Chọn giờ hẹn còn trống.');const r=await run(walkin?'walkin':'book',{...data,serviceIds:f.getAll('services'),start:Number(data.start),consent:f.has('consent')},'');bookingSuccess(ap(r.id),walkin);break;}
      case 'reschedule-form':{if(data.start===undefined)throw new Error('Chọn một giờ trống.');await run('reschedule',{id:form.dataset.id,date:data.date,techId:data.techId,start:Number(data.start)},'Đã đổi lịch.');appointmentDetail(form.dataset.id);break;}
      case 'pos-form':{const r=await run('checkout',posPayload(), 'Thanh toán demo hoàn tất.');receiptModal(r.id);break;}
      case 'customer-form':await run('customerSave',{...data,id:form.dataset.id,consent:f.has('consent')});closeModal();break;
      case 'gift-form':{const r=await run('giftSell',{recipient:data.recipient,amount:dollars(data.amount),method:data.method},'Đã phát hành gift card demo.');giftDetail(r.id);break;}
      case 'gift-lookup-form':{const g=S().giftCards.find(x=>x.code===data.code.trim().toUpperCase());if(!g)throw new Error('Không tìm thấy mã gift card.');giftDetail(g.id);break;}
      case 'refund-form':await run('refund',{id:form.dataset.id,reason:data.reason},'Đã hoàn toàn bộ hóa đơn demo.');receiptModal(form.dataset.id);break;
      case 'block-form':await run('block',{...data,start:fromTime(data.start),end:fromTime(data.end)});closeModal();break;
      case 'staff-form':await run('staffSave',data);closeModal();break;
      case 'service-form':await run('serviceSave',{...data,id:form.dataset.id,price:dollars(data.price),duration:Number(data.duration),active:f.has('active')});closeModal();break;
      case 'stock-form':await run('inventoryAdjust',{id:form.dataset.id,delta:Number(data.delta),reason:data.reason});closeModal();break;
      case 'settings-form':await run('settings',{open:fromTime(data.open),close:fromTime(data.close),taxBasisPoints:Math.round(Number(data.tax)*100),commissionRate:Number(data.commission),...Object.fromEntries(['countRequestedTurns','bookingMessages','receiptMessages','followupMessages','reminderMessages'].map(k=>[k,f.has(k)]))});break;
      case 'kiosk-lookup':case 'guest-lookup':{const normalized=data.phone.replace(/\D/g,'').replace(/^1(?=\d{10}$)/,'');if(normalized.length!==10)throw new Error('Nhập số điện thoại 10 chữ số.');const cs=S().customers.filter(c=>c.phone.replace(/\D/g,'')===normalized);const list=S().appointments.filter(a=>cs.some(c=>c.id===a.customerId)&&(form.id==='kiosk-lookup'?a.date===day()&&!['cancelled','no_show','completed'].includes(a.status):a.date>=day()));const html=list.length?list.map(a=>`<div class="queue-card card"><div class="person">${avatar(customer(a.customerId).name)}<div><h3>${esc(customer(a.customerId).name)}</h3><small>${dateLabel(a.date)} · ${time(a.start)} · ${esc(staff(a.techId).name)}</small></div><span class="spacer"></span>${badge(a.status)}</div><p style="font-size:12px">${esc(a.items.map(i=>i.name).join(' + '))}</p><div class="actions mt">${a.status==='booked'&&a.date===day()?btn('Check-in ngay','checkin',{cls:'primary',id:a.id}):''}${btn('Chi tiết / đổi lịch','appointment',{id:a.id})}</div></div>`).join(''):empty('Chưa tìm thấy lịch phù hợp','Bạn có thể đặt lịch mới hoặc check-in walk-in.',btn('Khách walk-in','walkin',{cls:'primary'}));if(form.id==='kiosk-lookup')$('#kiosk-results').innerHTML=html;else modal('Lịch hẹn của khách (demo)',html);break;}
    }
  }catch(e){if(form.id==='pos-form'&&$('#pos-error'))$('#pos-error').textContent=e.message;else if($('#modal').open&&$('#modal-error'))$('#modal-error').textContent=e.message;else toast(e.message,true);}
  finally{if(submit?.isConnected)submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{closeModal();searchQuery='';render();window.scrollTo(0,0);});
$('#modal').addEventListener('close',stopScan);
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!$('#modal').open){event.preventDefault();searchModal();}});
store.addEventListener('change',()=>{if(document.activeElement?.closest('#pos-form, #settings-form')){if($('#pos-form'))updatePos();return;}render();if($('#booking-form'))updateBooking();});
try{await store.init();render();if('serviceWorker'in navigator&&!window.SILVER_LOCAL_SERVER)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){$('#app').innerHTML=`<div class="loading"><h1>Chưa mở được demo</h1><p>${esc(e.message)}</p><p class="mt">Hãy cho phép lưu trữ dữ liệu trang web, rồi tải lại trang.</p><button class="btn primary mt" id="retry-load">Tải lại</button></div>`;$('#retry-load').onclick=()=>location.reload();}
